// Generated by scripts/sync-obsidian-runtime.mjs.
import { type App, Setting } from 'obsidian';
import { pluginInstallation } from './local-diagnostics';

export type DependencyState = 'missing' | 'waiting' | 'incompatible' | 'unbound' | 'ready' | 'unknown';
export function dependencyState(installed: boolean | null, connected: boolean, compatible: boolean, bound: boolean): DependencyState {
    if (!compatible) return 'incompatible';
    if (connected) return bound ? 'ready' : 'unbound';
    return installed === null ? 'unknown' : installed ? 'waiting' : 'missing';
}
export function pluginStoreUrl(id: 'clipmd' | 'clipmd-desktop-tools'): string {
    return `obsidian://show-plugin?id=${id}`;
}
export function renderDependency(container: HTMLElement, app: App, id: 'clipmd' | 'clipmd-desktop-tools', connection: () => { connected: boolean; compatible: boolean; bound: boolean }): () => void {
    const card = container.createDiv({ cls: 'clip2md-dependency-guide' });
    const title = id === 'clipmd' ? 'Clip2MD 主插件' : '本地剪藏扩展';
    let alive = true, busy = false, last = '';
    const refresh = async () => {
        if (!alive || busy) return;
        busy = true;
        let installed: boolean | null = null;
        try { const result = await pluginInstallation(app.vault.adapter, app.vault.configDir, id); installed = result.unknown ? null : result.installed; }
        catch { /* Keep lookup failures distinct from a missing plugin. */ }
        busy = false;
        if (!alive) return;
        const live = connection();
        const state = dependencyState(installed, live.connected, live.compatible, live.bound);
        if (state === last) return;
        last = state;
        card.empty();
        const descriptions: Record<DependencyState, string> = {
            missing: `尚未安装${title}，请打开社区插件页面安装并启用。`,
            waiting: `${title}已安装，正在等待连接；请确认已启用。`,
            incompatible: '联动协议不兼容，请更新两个插件后重试。',
            unbound: '插件已连接，请先在 Clip2MD 主插件中绑定账号。',
            ready: `${title}已连接。`,
            unknown: '暂时无法读取插件安装状态，请检查后重试。',
        };
        card.createEl('p', { text: descriptions[state] });
        if (state === 'ready') return;
        new Setting(card).addButton(button => button.setButtonText(state === 'missing' ? `安装${title}` : `打开${title}社区页面`).onClick(() => { window.open(pluginStoreUrl(id)); }));
        if (state === 'waiting' || state === 'unknown') new Setting(card).addButton(button => button.setButtonText('打开社区插件设置').onClick(() => {
            const settings = (app as App & { setting?: { open(): void; openTabById(id: string): void } }).setting;
            if (settings) { settings.open(); settings.openTabById('community-plugins'); }
            else window.open(pluginStoreUrl(id));
        }));
        if (state === 'unbound') new Setting(card).addButton(button => button.setButtonText('绑定 Clip2MD 账号').onClick(() => { window.open('obsidian://clipmd-settings'); }));
        new Setting(card).addButton(button => button.setButtonText('重新检查').onClick(() => { last = ''; void refresh(); }));
    };
    void refresh();
    const timer = window.setInterval(() => { void refresh(); }, 1500);
    return () => { alive = false; window.clearInterval(timer); card.remove(); };
}
